using Microsoft.EntityFrameworkCore;using OneBox.Api.Models;
namespace OneBox.Api.Data;
public sealed class OneBoxDb(DbContextOptions<OneBoxDb> options):DbContext(options){public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<OneTask> Tasks=>Set<OneTask>();public DbSet<ScheduledTask> ScheduledTasks=>Set<ScheduledTask>();public DbSet<TaskStep> TaskSteps=>Set<TaskStep>();public DbSet<AuditEvent> AuditEvents=>Set<AuditEvent>();public DbSet<Booking> Bookings=>Set<Booking>();public DbSet<PaymentTransaction> PaymentTransactions=>Set<PaymentTransaction>();public DbSet<ProviderHealth> ProviderHealth=>Set<ProviderHealth>();protected override void OnModelCreating(ModelBuilder b){b.Entity<AppUser>().HasIndex(x=>x.Email).IsUnique();b.Entity<OneTask>().HasIndex(x=>new{x.UserId,x.CreatedAt});b.Entity<ScheduledTask>().HasIndex(x=>new{x.Status,x.NextCheckAtUtc});b.Entity<ScheduledTask>().HasIndex(x=>new{x.UserId,x.CreatedAt});b.Entity<Booking>().HasIndex(x=>x.ProviderReference).IsUnique();b.Entity<TaskStep>().HasIndex(x=>new{x.TaskId,x.StepOrder}).IsUnique();b.Entity<OneTask>().HasIndex(x=>x.ExecutionKey).IsUnique();b.Entity<PaymentTransaction>().HasIndex(x=>new{x.UserId,x.CreatedAt});b.Entity<ProviderHealth>().HasIndex(x=>x.Provider).IsUnique();b.Entity<AuditEvent>().HasIndex(x=>new{x.UserId,x.CreatedAt});b.Entity<OneTask>().HasMany(x=>x.Steps).WithOne().HasForeignKey(x=>x.TaskId).OnDelete(DeleteBehavior.Cascade);}}
